using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using Object=UnityEngine.Object;
public static class GridShiftV7Setup {
 [MenuItem("GridShift/Atualização 7.0/Configurar destinos e minimapa")]
 public static void Configure(){if(EditorApplication.isPlaying)throw new Exception("Saia do Play Mode e salve suas cenas antes de configurar.");int worldLayer=Layer("DeliveryWorld");var scene=EditorSceneManager.OpenScene("Assets/Scenes/SampleScene.unity");var manager=Object.FindFirstObjectByType<DeliveryManager>();if(manager==null)throw new Exception("Configure a atualização de entregas primeiro.");var report=new List<string>();int initial=manager.points.Length;Expand(manager);manager.GetComponent<DeliveryPresentation>().worldMarkerLayer=worldLayer;Cameras(worldLayer);EditorUtility.SetDirty(manager);EditorSceneManager.SaveScene(scene);report.Add("Pontos anteriores: "+initial+"; pontos atuais: "+manager.points.Count(p=>p!=null&&p.Valid));foreach(var group in manager.points.GroupBy(p=>p.requiredExpansion))report.Add("Nível de parceiros "+group.Key+": "+group.Count()+" locais");foreach(var group in manager.points.GroupBy(p=>p.establishmentType))report.Add(group.Key+": "+group.Count());scene=EditorSceneManager.OpenScene("Assets/Scenes/Office.unity");Cameras(worldLayer);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();File.WriteAllLines("v7-setup.txt",report);}
 public static void Batch(){Configure();EditorApplication.Exit(0);}
 static int Layer(string name){int existing=LayerMask.NameToLayer(name);if(existing>=0)return existing;var so=new SerializedObject(AssetDatabase.LoadAllAssetsAtPath("ProjectSettings/TagManager.asset")[0]);var layers=so.FindProperty("layers");for(int i=11;i<32;i++)if(string.IsNullOrEmpty(layers.GetArrayElementAtIndex(i).stringValue)){layers.GetArrayElementAtIndex(i).stringValue=name;so.ApplyModifiedPropertiesWithoutUndo();return i;}throw new Exception("Nenhuma layer disponível.");}
 static void Cameras(int layer){foreach(var c in Object.FindObjectsByType<Camera>(FindObjectsSortMode.None)){if(c.GetComponent<MinimapCamera>()!=null){c.cullingMask&=~((1<<layer)|(1<<5)|(1<<7)|(1<<8)|(1<<10));c.GetComponent<UnityEngine.Rendering.Universal.UniversalAdditionalCameraData>().renderPostProcessing=false;}else c.cullingMask|=1<<layer;}}
 static string Type(string name){name=name.ToLowerInvariant();return name.Contains("bakery")?"Padaria":name.Contains("pharma")?"Farmácia":name.Contains("auto")?"Oficina":name.Contains("gas")?"Posto":name.Contains("warehouse")||name.Contains("depot")?"Depósito":name.Contains("market")?"Mercado":name.Contains("coffee")?"Cafeteria":name.Contains("house")?"Residência":name.Contains("shop")?"Comércio":"Prédio";}
 static void Expand(DeliveryManager manager){var points=manager.points.Where(p=>p!=null).ToList();foreach(var p in points){p.establishmentType=Type(p.name);p.displayName=p.establishmentType+" · "+p.name.Replace("Delivery_Building_","").Replace('_',' ');}var routes=Object.FindObjectsByType<TrafficRoute>(FindObjectsSortMode.None).Where(r=>r.Valida&&Vector3.Distance(r.pontos[0].position,r.pontos[1].position)>25).OrderBy(r=>r.name).ToArray();var buildings=Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None).Where(r=>r.name.StartsWith("Building_")).OrderBy(r=>r.name).ThenBy(r=>r.transform.position.x).ToArray();var root=GameObject.Find("DeliveryPoints").transform;int added=points.Count(p=>p.name.StartsWith("Partner_"));foreach(var building in buildings){if(added>=40)break;var candidates=new List<(TrafficRoute route,Vector3 stop,float distance)>();foreach(var route in routes){var a=route.pontos[0].position;var direction=(route.pontos[1].position-a).normalized;float max=Vector3.Distance(a,route.pontos[1].position)-6;if(route.GetParada(out var line,out _))max=Mathf.Min(max,Vector3.Dot(line-a,direction)-12);if(max<10)continue;var stop=a+direction*Mathf.Clamp(Vector3.Dot(building.bounds.center-a,direction),10,max);float distance=Vector3.ProjectOnPlane(stop-building.bounds.center,Vector3.up).sqrMagnitude;if(distance>32*32||points.Any(p=>Vector3.Distance(p.Stop,stop)<5.5f)||!Road(stop,direction))continue;if(DeliveryRouting.Find(points[0].route,route)==null||DeliveryRouting.Find(route,points[0].route)==null)continue;candidates.Add((route,stop,distance));}if(candidates.Count==0)continue;var best=candidates.OrderBy(c=>c.distance).First();string id="P7-"+Hash128.Compute(building.name+best.route.name+best.stop.ToString("F2",System.Globalization.CultureInfo.InvariantCulture)).ToString().Substring(0,12);if(points.Any(p=>p.id==id))continue;var pnt=new GameObject("Partner_"+building.name).AddComponent<DeliveryPoint>();pnt.transform.SetParent(root);var directionToBuilding=Vector3.ProjectOnPlane(building.bounds.center-best.stop,Vector3.up).normalized;var at=best.stop+directionToBuilding*5.5f;var ground=Physics.RaycastAll(at+Vector3.up*20,Vector3.down,40,~0,QueryTriggerInteraction.Ignore).Where(h=>h.collider.name.IndexOf("Building",StringComparison.OrdinalIgnoreCase)<0&&h.collider.GetComponentInParent<TrafficCar>()==null).OrderBy(h=>h.distance).FirstOrDefault();pnt.transform.position=ground.collider!=null&&ground.point.y<best.stop.y+1?ground.point+Vector3.up*.04f:best.stop+Vector3.up*.1f;var stopPoint=new GameObject("VehicleStop").transform;stopPoint.SetParent(pnt.transform);stopPoint.position=best.stop;pnt.vehicleStop=stopPoint;pnt.route=best.route;pnt.segment=0;pnt.accessible=true;pnt.requiredExpansion=added/10;pnt.id=id;pnt.establishmentType=Type(building.name);pnt.displayName=pnt.establishmentType+" · Parceiro "+(added+1).ToString("00");points.Add(pnt);added++;}manager.points=points.ToArray();}
 static bool Road(Vector3 at,Vector3 direction){if(!Physics.RaycastAll(at+Vector3.up*3,Vector3.down,8,~0,QueryTriggerInteraction.Ignore).Any(h=>h.collider.name.StartsWith("Road ")))return false;foreach(var c in Physics.OverlapBox(at+Vector3.up*1.6f,new Vector3(1.8f,1.1f,4.8f),Quaternion.LookRotation(direction),~0,QueryTriggerInteraction.Ignore))if(!c.name.StartsWith("Road ")&&c.GetComponentInParent<PlayerMovement>()==null)return false;return true;}
}
